<?php
namespace App\Http\Controllers\Admin;
use App\Actions\Catalog\ModerateCatalogDomain;use App\Http\Controllers\Controller;use App\Models\CatalogEntity;use App\Models\Review;use App\Services\AuditLogger;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
abstract class DomainModerationController extends Controller
{protected string $domain;protected string $permission;protected string $title;public function index(Request $r):View{abort_unless($r->user()->can($this->permission),403);$items=CatalogEntity::whereIn('status',['submitted','under_review'])->whereHas('serviceType',fn($q)=>$q->where('code',$this->domain))->with(['mitra','category'])->oldest('updated_at')->paginate(20);$reviews=Review::where('status','pending')->whereHas('catalogEntity.serviceType',fn($q)=>$q->where('code',$this->domain))->with(['user','catalogEntity'])->paginate(10,['*'],'reviews');return view('admin.catalog-domain.index',['items'=>$items,'reviews'=>$reviews,'title'=>$this->title,'routePrefix'=>'admin.'.$this->domain]);}public function show(Request $r,CatalogEntity $item):View{abort_unless($r->user()->can($this->permission)&&$item->serviceType()->where('code',$this->domain)->exists(),403);return view('admin.catalog-domain.show',['item'=>$item->load(['mitra','category','region','location','facilities','media','moderationReports.actions.actor']),'title'=>$this->title,'routePrefix'=>'admin.'.$this->domain]);}public function update(Request $r,CatalogEntity $item,ModerateCatalogDomain $a):RedirectResponse{abort_unless($r->user()->can($this->permission)&&$item->serviceType()->where('code',$this->domain)->exists(),403);$d=$r->validate(['decision'=>'required|in:approve,reject,takedown','reason'=>'nullable|required_if:decision,reject,takedown|string|max:2000']);$a->execute($item,$this->domain,$d['decision'],$d['reason']??null,$r->user());return back()->with('status','Keputusan moderasi disimpan.');}public function review(Request $r,Review $review,AuditLogger $audit):RedirectResponse{abort_unless($r->user()->can($this->permission)&&$review->catalogEntity->serviceType()->where('code',$this->domain)->exists(),403);$d=$r->validate(['decision'=>'required|in:publish,reject','reason'=>'nullable|required_if:decision,reject|string']);$review->update(['status'=>$d['decision']==='publish'?'published':'rejected','moderated_by'=>$r->user()->id,'moderated_at'=>now()]);$e=$review->catalogEntity;$stats=$e->reviews()->where('status','published')->selectRaw('COUNT(*) total,COALESCE(AVG(rating),0) average')->first();$e->update(['rating_count'=>$stats->total,'rating_average'=>$stats->average]);$audit->record($this->domain.'.review_'.$d['decision'],$e,[],['review_id'=>$review->id],$r->user());return back();}}
